{"category_edits":[{"category":"learning_objective","rationale":"For all four datasets, retain the existing weighted pairwise objective and add a 0.1-weighted mean softplus ranking loss over the same padding-masked positive-negative pairs. This may improve ranking while preserving the GRU architecture, sampling, training settings, and single-model prediction.","edits":[{"find":"    weights = torch.softmax(valid_neg.detach(), dim=0)
    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)
    return (weights * pairwise_loss).sum()","replace":"    weights = torch.softmax(valid_neg.detach(), dim=0)
    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)
    existing_loss = (weights * pairwise_loss).sum()
    return existing_loss + 0.1 * pairwise_loss.mean()"}]}],"change_summary":"Add the specified masked pairwise auxiliary loss across all four categories. No predictor changes are required."}
